begin;
insert into auth.users(id) values('a7777777-7777-4777-8777-777777777777'),('b7777777-7777-4777-8777-777777777777');
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"sub":"a7777777-7777-4777-8777-777777777777"}',true);
set local role authenticated;
do $$declare x jsonb;y jsonb;pid uuid;cid uuid;note_id uuid;bad boolean;begin
 perform public.kiyi_command('profile','{"username":"stage6_a","searchable":true}');
 x=public.kiyi_command('post_create','{"text":"Stage 6 test"}');pid=(x->'post'->>'id')::uuid;
 x=public.kiyi_command('badges');assert x->'badges' @> '[{"code":"first_post"}]','First post badge';
 x=public.kiyi_command('bundle');assert (select count(*) from jsonb_array_elements(x->'notifications')n where n->>'kind'='badge' and n->>'badge_code'='first_post')=1,'Badge notification';
 perform public.kiyi_command('like',jsonb_build_object('id',pid,'like',true));x=public.kiyi_command('bundle');assert not x->'notifications' @> '[{"kind":"like"}]','Self like notification';
 perform set_config('request.jwt.claims','{"sub":"b7777777-7777-4777-8777-777777777777"}',true);
 perform public.kiyi_command('profile','{"username":"stage6_b","searchable":true}');
 perform public.kiyi_command('follow','{"target":"a7777777-7777-4777-8777-777777777777","enabled":true}');
 perform public.kiyi_command('like',jsonb_build_object('id',pid,'like',true));
 x=public.kiyi_command('comment',jsonb_build_object('id',pid,'text','Stage 6 comment'));cid=(x->'post'->'comments'->0->>'id')::uuid;
 x=public.kiyi_command('content_report',jsonb_build_object('kind','post','id',pid,'reason','Spam'));y=public.kiyi_command('content_report',jsonb_build_object('kind','post','id',pid,'reason','Diğer'));assert x->>'id'=y->>'id','Duplicate report';
 x=public.kiyi_command('my_reports');assert jsonb_array_length(x->'reports')=1,'Reporter history';
 perform set_config('request.jwt.claims','{"sub":"a7777777-7777-4777-8777-777777777777"}',true);
 x=public.kiyi_command('bundle');assert x->'notifications' @> '[{"kind":"follow"}]' and x->'notifications' @> '[{"kind":"like"}]' and x->'notifications' @> '[{"kind":"comment"}]','Missing social notifications';
 select (n->>'id')::uuid into note_id from jsonb_array_elements(x->'notifications')n where n->>'kind'='like';
 perform public.kiyi_command('notification_open',jsonb_build_object('id',note_id));
 x=public.kiyi_command('bundle');assert exists(select 1 from jsonb_array_elements(x->'notifications')n where n->>'id'=note_id::text and n->>'read_at' is not null),'Read state';
 x=public.kiyi_command('my_reports');assert jsonb_array_length(x->'reports')=0,'Foreign reports exposed';
 perform public.kiyi_command('notification_settings','{"settings":{"comment":false}}');
 x=public.kiyi_command('notification_settings');assert x->'settings'->>'comment'='false','Saved preference read';
 x=public.kiyi_command('bundle');assert x->'notificationSettings'->>'comment'='false','Bundle preference read';
 perform set_config('request.jwt.claims','{"sub":"b7777777-7777-4777-8777-777777777777"}',true);
 bad=false;begin perform public.kiyi_command('notification_open',jsonb_build_object('id',note_id));exception when insufficient_privilege then bad=true;end;assert bad,'Foreign notification read';
 perform public.kiyi_command('like',jsonb_build_object('id',pid,'like',false));perform public.kiyi_command('like',jsonb_build_object('id',pid,'like',true));
 perform public.kiyi_command('comment',jsonb_build_object('id',pid,'text','Preference disabled second comment'));
 perform set_config('request.jwt.claims','{"sub":"a7777777-7777-4777-8777-777777777777"}',true);
 x=public.kiyi_command('bundle');assert (select count(*) from jsonb_array_elements(x->'notifications')n where n->>'kind'='like')=1,'Repeated like notification';assert (select count(*) from jsonb_array_elements(x->'notifications')n where n->>'kind'='comment')=1,'Preference ignored';
 perform public.kiyi_command('block','{"target":"b7777777-7777-4777-8777-777777777777","enabled":true}');
 x=public.kiyi_command('bundle');assert not exists(select 1 from jsonb_array_elements(x->'notifications')n where n->>'sender'='b7777777-7777-4777-8777-777777777777'),'Blocked identity in inbox';
 bad=false;begin perform public.kiyi_command('badges','{"target":"b7777777-7777-4777-8777-777777777777"}');exception when insufficient_privilege then bad=true;end;assert bad,'Blocked badges';
 bad=false;begin update public.kiyi_badges set code='verified';exception when insufficient_privilege then bad=true;end;assert bad,'Direct badge write';
 bad=false;begin select * into x from public.kiyi_notifications limit 1;exception when insufficient_privilege then bad=true;end;assert bad,'Direct notification read';
end$$;
reset role;
select 'PASS stage6 badge/dedupe/self-like/social notifications/preferences/read/report/isolation/block/direct grants' as result;
rollback;
